begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b1200000-0000-0000-0000-000000000001','authenticated','authenticated','p12a@example.test','',now(),'{}','{"name":"Payment A","company_name":"Payment A"}',now(),now()),
('b1200000-0000-0000-0000-000000000002','authenticated','authenticated','p12b@example.test','',now(),'{}','{"name":"Payment B","company_name":"Payment B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b1200000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('p12.company',private.current_company_id(),true);
update public.companies set store_domain='payment-a.example.test' where id=current_setting('p12.company');
select set_config('p12.bank',public.finance_command(gen_random_uuid(),'account_create','{"name":"Payment QA bank","kind":"bank","amount":0}')#>>'{account,id}',true);
insert into public.orders(id,company_id,customer_name,number,status,total_amount,paid_amount,created_at) select 'p12-'||v,current_setting('p12.company'),'Synthetic payment customer','PED-12'||n,'finalizado',100,0,'2000-01-10T12:00Z' from (values('good','01'),('partial','02'),('real','03'),('specific','04'),('legacy','05'),('expired','06'),('cancel','07'),('changed','08'),('race','09')) x(v,n);
insert into private.payment_qa_fixtures(company_id,order_id,account_id,paid_at) select company_id,id,current_setting('p12.bank')::uuid,'2000-01-20T12:00Z' from public.orders where company_id=current_setting('p12.company') and id like 'p12-%' and id<>'p12-real';
insert into public.financial_transactions(id,company_id,order_id,order_number,type,category,amount,payment_method,status,due_date,source) values
('p12-specific',current_setting('p12.company'),'p12-specific','PED-1204','receita','Vendas',100,'faturado','pendente','2000-01-20','order_payment'),
('p12-legacy',current_setting('p12.company'),null,'ORD-1205','receita','Vendas',100,'faturado','pendente','2000-01-20','order_payment'),
('p12-changed',current_setting('p12.company'),'p12-changed','PED-1208','receita','Vendas',100,'faturado','pendente','2000-01-20','order_payment');
create function pg_temp.p12_create(o text,extra jsonb default '{}') returns uuid language sql as $$select (public.payment_link_command(gen_random_uuid(),'create',jsonb_build_object('order_id','p12-'||o,'provider','qa','expires_on',(now() at time zone 'America/Bahia')::date)||extra)->>'id')::uuid$$;
create function pg_temp.p12_command(action text,id uuid) returns jsonb language sql as $$select public.payment_link_command(gen_random_uuid(),action,jsonb_build_object('id',id,'revision',(select revision from public.payment_links where payment_links.id=$2)))$$;
grant execute on function pg_temp.p12_create(text,jsonb),pg_temp.p12_command(text,uuid) to authenticated;
select ok(not has_function_privilege('anon','public.payment_links_source(text)','execute'),'anon cannot list links');
select ok(not has_function_privilege('authenticated','public.payment_link_webhook(jsonb)','execute'),'browser cannot confirm payments');
select ok(not has_function_privilege('authenticated','public.payment_provider_secret()','execute'),'secret is server-only');
select ok(not has_table_privilege('authenticated','public.payment_links','insert'),'browser cannot forge links');
select ok(not has_function_privilege('authenticated','private.finance_apply_order_payment(text,text,numeric,text,text,timestamptz,text,timestamptz,uuid)','execute'),'shared core is private');
set local role authenticated;
select throws_ok($$select pg_temp.p12_create('real')$$,'22023','Provedor real não configurado. QA disponível somente para fixtures autorizadas.','QA cannot target a real Order');
select throws_ok($$select pg_temp.p12_create('good','{"amount":101}')$$,'22023','Valor deve ser positivo e não superar o saldo.','over-balance amount rejected');
select throws_ok($$select pg_temp.p12_create('good','{"amount":0}')$$,'22023','Valor deve ser positivo e não superar o saldo.','zero rejected');
select throws_ok($$select pg_temp.p12_create('good','{"amount":0.001}')$$,'22023','Valor deve ser positivo e não superar o saldo.','fractional cent rejected');
select throws_ok($$select pg_temp.p12_create('good','{"provider":"live"}')$$,'22023','Provedor indisponível.','provider failure cannot create fake live link');
select throws_ok($$select pg_temp.p12_create('specific')$$,'22023','Selecione o recebível específico deste Pedido.','specific receivable preferred over residual aggregate');
select throws_ok($$select pg_temp.p12_create('specific','{"receivable_id":"p12-specific","amount":20}')$$,'22023','Recebível específico exige valor integral.','specific installment partial unsupported explicitly');
select set_config('p12.good',pg_temp.p12_create('good')::text,true);
select set_config('p12.partial',pg_temp.p12_create('partial','{"amount":25.13}')::text,true);
select set_config('p12.specific',pg_temp.p12_create('specific','{"receivable_id":"p12-specific"}')::text,true);
select set_config('p12.legacy',pg_temp.p12_create('legacy','{"receivable_id":"p12-legacy"}')::text,true);
select set_config('p12.expired',pg_temp.p12_create('expired')::text,true);
select set_config('p12.cancel',pg_temp.p12_create('cancel')::text,true);
select set_config('p12.changed',pg_temp.p12_create('changed','{"receivable_id":"p12-changed"}')::text,true);
select set_config('p12.race',pg_temp.p12_create('race')::text,true);
select is((select amount from public.payment_links where id=current_setting('p12.partial')::uuid),25.13::numeric,'partial link exact amount');
select is(public.payment_links_source()#>>'{rows,0,expires_on}',(now() at time zone 'America/Bahia')::date::text,'displayed expiry equals selected civil day, not following midnight');
select is(jsonb_array_length(public.payment_links_source()->'rows'),8,'source scoped to current tenant');
reset role;
select set_config('p12.event',pg_temp.p12_command('qa_prepare',current_setting('p12.good')::uuid)::text,true);
select set_config('p12.token',(select token from private.payment_link_tokens where link_id=current_setting('p12.good')::uuid),true);
select is(length(current_setting('p12.token')),64,'token is 256-bit random hexadecimal');
select is((select token_hash from public.payment_links where id=current_setting('p12.good')::uuid),encode(extensions.digest(current_setting('p12.token'),'sha256'),'hex'),'public table holds hash rather than bearer token');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.payment_public_source(current_setting('p12.token'),'payment-a.example.test')->>'status','active','valid public token and matching host');
select is(public.payment_public_source(current_setting('p12.token'),'payment-a.example.test')->>'expires_on',(now() at time zone 'America/Bahia')::date::text,'public expiry displays selected civil date');
select is(public.payment_public_source(current_setting('p12.token'),'other.example.test'),null::jsonb,'token cannot cross tenant hostname');
select is(public.payment_public_source(repeat('0',64),'payment-a.example.test'),null::jsonb,'enumeration misses are uniform');
select ok(not (public.payment_public_source(current_setting('p12.token'),'payment-a.example.test') ?| array['company_id','order_id','receivable_id','notes','transaction_id','token_hash']),'public DTO excludes internals');
select public.payment_link_webhook(current_setting('p12.event')::jsonb);
select public.payment_link_webhook(current_setting('p12.event')::jsonb);
select is(public.payment_link_webhook(current_setting('p12.event')::jsonb||jsonb_build_object('event_id','other-event'))->>'result','ignored','different event same payment cannot pay twice');
select throws_ok($$select public.payment_link_webhook(current_setting('p12.event')::jsonb||'{"amount":99}')$$,'22023','Event key reused','same event with changed payload rejected');
reset role;
select is((select count(*)::integer from public.financial_transactions where order_id='p12-good'),1,'one canonical receipt after retries');
select is((select paid_amount from public.orders where id='p12-good'),100::numeric,'Order paid through canonical core');
select is((select payment_status from public.orders where id='p12-good'),'pago','canonical Order payment status');
select is((select status from public.orders where id='p12-good'),'finalizado','link does not invent Order workflow');
select is((select status from public.payment_links where id=current_setting('p12.good')::uuid),'paid','link paid only after receipt');
select is((select count(*)::integer from public.audit_logs where company_id=current_setting('p12.company') and action='payment_link.confirmed'),1,'duplicate event does not duplicate Audit Log');
select is((select actor_name from public.audit_logs where company_id=current_setting('p12.company') and action='payment_link.confirmed'),'SYSTEM','webhook actor is SYSTEM without impersonation');
select is((select count(*)::integer from public.cash_register_transactions where description like '%PED-1201%'),0,'online bank receipt does not mirror current physical cash session');
select set_config('request.jwt.claims','{"sub":"b1200000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select pg_temp.p12_command('cancel',current_setting('p12.good')::uuid)$$,'22023','Pagamento confirmado não pode ser cancelado pelo link.','paid link cannot be cancelled');
select pg_temp.p12_command('cancel',current_setting('p12.cancel')::uuid);
reset role;
create function pg_temp.p12_event(id uuid,state text default 'paid') returns jsonb language sql security definer set search_path='' as $$select jsonb_build_object('event_id',gen_random_uuid(),'external_id',external_id,'payment_id','qa:'||external_id,'state',$2,'amount',amount,'currency','BRL') from public.payment_links where payment_links.id=$1$$;
grant execute on function pg_temp.p12_event(uuid,text) to service_role;
update public.payment_links set expires_at=now()-interval '1 second' where id=current_setting('p12.expired')::uuid;
update public.financial_transactions set type='despesa' where id='p12-changed';
update public.orders set paid_amount=100,payment_status='pago' where id='p12-race';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.expired')::uuid))->>'result','divergent','late confirmation after expiry is explicit divergence');
select is(public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.cancel')::uuid))->>'result','divergent','late confirmation after cancellation is explicit divergence');
select is(public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.changed')::uuid))->>'result','divergent','changed receivable type cannot settle unrelated expense');
select is(public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.race')::uuid))->>'result','divergent','manual payment before webhook cannot truncate confirmed amount');
select public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.partial')::uuid));
select public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.specific')::uuid));
select public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.legacy')::uuid));
select is(public.payment_public_source(current_setting('p12.token'),'payment-a.example.test')->>'status','paid','public status follows canonical confirmed payment');
reset role;
select is((select paid_amount from public.orders where id='p12-partial'),25.13::numeric,'partial payment exact with residual balance');
select is(private.payment_order_balance(current_setting('p12.company'),'p12-partial'),74.87::numeric,'balance remains canonical residual');
select is((select count(*)::integer from public.financial_transactions where order_id='p12-specific'),1,'specific receivable settled in place without second receipt');
select is((select status from public.financial_transactions where id='p12-specific'),'pago','specific receipt paid');
select is((select paid_amount from public.orders where id='p12-legacy'),100::numeric,'legacy ORD/PED receivable updates canonical Order');
select is((select account_id from public.financial_transactions where id='p12-legacy'),current_setting('p12.bank')::uuid,'verified account applied to specific receipt');
-- Cache can lag the canonical ledger; verified settlement must still finish at the true total.
insert into public.orders(id,company_id,customer_name,number,status,total_amount,paid_amount) values('p12-cache',current_setting('p12.company'),'Synthetic stale cache','PED-1299','finalizado',100,0);
insert into private.payment_qa_fixtures values(current_setting('p12.company'),'p12-cache',current_setting('p12.bank')::uuid,'2000-01-20T12:00Z',true);
insert into public.financial_transactions(company_id,order_id,order_number,type,category,amount,payment_method,status,due_date,paid_at) values(current_setting('p12.company'),'p12-cache','PED-1299','receita','Vendas',20,'pix','pago','2000-01-10','2000-01-10T12:00Z');
select set_config('request.jwt.claims','{"sub":"b1200000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('p12.cache',pg_temp.p12_create('cache')::text,true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.payment_link_webhook(pg_temp.p12_event(current_setting('p12.cache')::uuid));
select is((select paid_amount from public.orders where id='p12-cache'),100::numeric,'verified receipt repairs stale paid cache using canonical ledger balance');
select is((select payment_status from public.orders where id='p12-cache'),'pago','verified receipt status matches ledger total after stale cache');
select is((select count(*)::integer from public.financial_transactions where order_id in ('p12-expired','p12-cancel','p12-race')),0,'divergent events did not create receipts');
-- Reprocess a verified divergence only after an authorized source correction, never by redirect.
update public.orders set paid_amount=0,payment_status='pendente' where id='p12-race';
select set_config('request.jwt.claims','{"sub":"b1200000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.p12_command('reconcile',current_setting('p12.race')::uuid);
reset role;
select is((select status from public.payment_links where id=current_setting('p12.race')::uuid),'paid','reconcile verified event after explicit correction');
select is((select new_values->>'status' from public.audit_logs where company_id=current_setting('p12.company') and action='payment_link.reconciled'),'paid','reconcile audits fresh state');
select set_config('printflow.finance_command','on',true);
update public.financial_transactions set reversed_at=now() where order_id='p12-good';
select set_config('printflow.finance_command','off',true);
select is(private.payment_link_status((select p from public.payment_links p where id=current_setting('p12.good')::uuid)),'refunded','canonical reversal reflected without deleting history');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.payment_link_webhook(current_setting('p12.event')::jsonb);
reset role;
select is((select count(*)::integer from public.financial_transactions where order_id='p12-good'),1,'old paid replay cannot repay a reversed receipt');
select set_config('request.jwt.claims','{"sub":"b1200000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::integer from public.payment_links),0,'tenant B sees no links A');
select throws_ok($$select pg_temp.p12_command('cancel',current_setting('p12.partial')::uuid)$$,'P0002','Link indisponível.','cross tenant mutation denied');
reset role;
select set_config('request.jwt.claims','{"sub":"b1200000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into public.role_permissions(company_id,path,roles) values(current_setting('p12.company'),'/financial',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select throws_ok($$select public.payment_links_source()$$,'42501','Payment access denied','explicit admin financial denial respected');
select throws_ok($$select pg_temp.p12_create('partial')$$,'42501','Payment access denied','write permission denied');
reset role;
select * from finish();
rollback;
